description:
Create a `FocusableInput` component that accepts a `ref` via `forwardRef` and exposes a `focus()` method on that ref using `useImperativeHandle`. Calling `ref.current.focus()` should focus the underlying `<input>` element.

**Example:**
```tsx
const ref = useRef<{ focus: () => void }>(null);
<FocusableInput ref={ref} />
// later:
ref.current?.focus();
```

starter_code:
import { forwardRef, useRef, useImperativeHandle } from 'react';

export const FocusableInput = forwardRef(function FocusableInput(_props, ref) {
  // your code here
});

test_suite:
test('renders an input element', () => {
  const { container } = render(<FocusableInput />);
  expect(container.querySelector('input')).toBeTruthy();
});

test('ref is defined after mount', () => {
  const ref = { current: null } as any;
  render(<FocusableInput ref={ref} />);
  expect(ref.current).not.toBeNull();
});

test('ref exposes focus method', () => {
  const ref = { current: null } as any;
  render(<FocusableInput ref={ref} />);
  expect(typeof ref.current.focus).toBe('function');
});

test('calling ref.current.focus() focuses the input', () => {
  const ref = { current: null } as any;
  const { container } = render(<FocusableInput ref={ref} />);
  const input = container.querySelector('input') as HTMLInputElement;
  const focusSpy = vi.spyOn(input, 'focus');
  act(() => ref.current.focus());
  expect(focusSpy).toHaveBeenCalled();
});

// __hidden__
test('does not expose other internal methods on ref', () => {
  const ref = { current: null } as any;
  render(<FocusableInput ref={ref} />);
  const keys = Object.keys(ref.current);
  expect(keys).toEqual(['focus']);
});

solution:
import { forwardRef, useRef, useImperativeHandle } from 'react';

export const FocusableInput = forwardRef(function FocusableInput(_props, ref) {
  const inputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    focus() {
      inputRef.current?.focus();
    },
  }));

  return <input ref={inputRef} />;
});
